('6bc3e2e4-8b92-58d2-84cc-c4418e5ce225', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Dewrêşê Evdî" destana devkî ye ku li ser wefadarî û şer tê gotin.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Dewrêşê Evdî destaneke devkî ye ku dengbêj dibêjin; behsa wefadarî, mêranî û şer dike û bûyerên lehengiyê vedibêje.', 'Rast e. Dewrêşê Evdî destaneke devkî ye ku dengbêj dibêjin; behsa wefadarî, mêranî û şer dike û bûyerên lehengiyê vedibêje.', 'Doğru. Dewrêşê Evdî, dengbêjlerin söylediği sözlü bir destandır; vefa, yiğitlik ve savaşı, kahramanlık olaylarını anlatır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0004
('127ecd68-5071-507e-8de2-64b6fdd2e649', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Dewrêşê Evdî" çîroka gelêrî ye ku li ser sedaqet û ceribandinê ye.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Zembîlfiroş" e; "Dewrêşê Evdî" destana devkî ye ku li ser wefadarî û şer tê gotin.', 'Na — ev ravekirina "Zembîlfiroş" e; "Dewrêşê Evdî" destana devkî ye ku li ser wefadarî û şer tê gotin.', 'Hayır — bu tanım "Zembîlfiroş" kavramına ait; "Dewrêşê Evdî", sadakat ve savaş üzerine söylenen sözlü destandır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0005
('f18e946f-043e-5a69-b0a2-1509031d9dd9', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Zembîlfiroş" çîroka gelêrî ye ku li ser sedaqet û ceribandinê ye.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Zembîlfiroş çîrokeke gelêrî ye; behsa zilamekî feqîr û sedaqetxwaz dike ku li hember ceribandinê paqijiya xwe diparêze.', 'Rast e. Zembîlfiroş çîrokeke gelêrî ye; behsa zilamekî feqîr û sedaqetxwaz dike ku li hember ceribandinê paqijiya xwe diparêze.', 'Doğru. Zembîlfiroş bir halk hikâyesidir; yoksul ama namuslu bir adamın sınanma karşısında temiz kalmasını anlatır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0006
('97e254bf-2482-540e-847a-9b3169fec85e', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Mewlûda Kurdî" berhema olî ye ku Melayê Bateyî bi kurmancî nivîsî.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Mewlûda Kurdî berhemeke dînî ya Melayê Bateyî ye; bi kurmancî jidayikbûn û jiyana Pêxember vedibêje û di civatên dînî de tê xwendin.', 'Rast e. Mewlûda Kurdî berhemeke dînî ya Melayê Bateyî ye; bi kurmancî jidayikbûn û jiyana Pêxember vedibêje û di civatên dînî de tê xwendin.', 'Doğru. Mewlûda Kurdî, Melayê Bateyî''nin Kurmancî yazdığı dinî eserdir; Hz. Muhammed''in doğumunu ve hayatını anlatır, dinî toplantılarda okunur.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0008
