('d09e0d7e-13fa-5a71-94d5-df1aced393cf', (select id from categories where name = 'Edebiyat'), 'ku-kmr', '"Elî Herîrî" helbestvanê klasîk ê soranî ye ku ekola Baban temsîl dike. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina "Nalî" ye; "Elî Herîrî" yek ji helbestvanên klasîk ên herî kevn ên wêjeya kurdî ye.', 'Na — ev ravekirina "Nalî" ye; "Elî Herîrî" yek ji helbestvanên klasîk ên herî kevn ên wêjeya kurdî ye.', 'Hayır — bu tanım "Nalî" kavramına ait; "Elî Herîrî", Kürt edebiyatının en eski klasik şairlerinden biridir.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0011
('4fcedc88-65bc-5c62-a2a4-214245629606', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Nalî" helbestvanê klasîk ê soranî ye ku ekola Baban temsîl dike.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Nalî helbestvanekî klasîk ê soranî ye; bi Salim û Kurdî re yek ji sê stûnên ekola Baban tê hesibandin.', 'Rast e. Nalî helbestvanekî klasîk ê soranî ye; bi Salim û Kurdî re yek ji sê stûnên ekola Baban tê hesibandin.', 'Doğru. Nalî klasik Soranî şiirin şairidir; Salim ve Kurdî ile birlikte Baban ekolünün üç direğinden biri sayılır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0012
