('7cd04ebc-b82f-50f4-bee6-c525ef75348a', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Osman Sebrî" nivîskar û helbestvan e ku li Şamê di weşangeriya kurdî de xebitî.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Osman Sebrî nivîskar û helbestvanekî kurd e; beşeke dirêj a jiyana xwe li Şamê derbas kir û di rojname û kovarên kurdî de nivîsî.', 'Rast e. Osman Sebrî nivîskar û helbestvanekî kurd e; beşeke dirêj a jiyana xwe li Şamê derbas kir û di rojname û kovarên kurdî de nivîsî.', 'Doğru. Osman Sebrî Kürt yazar ve şairdir; yaşamının uzun bir bölümünü Şam''da geçirdi, Kürtçe gazete ve dergilerde yazdı.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0014
