('dac9c640-4e9e-570d-b05e-f68dce0bdcde', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "Qanatê Kurdo" zimannas û kurdolojîst e ku rêzimana kurmancî bi awayekî zanistî nivîsî.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Qanatê Kurdo zimannas û kurdolog e; bi xebatên xwe yên li ser rêziman û zaravayên kurdî, bi taybetî kurmancî, tê naskirin.', 'Rast e. Qanatê Kurdo zimannas û kurdolog e; bi xebatên xwe yên li ser rêziman û zaravayên kurdî, bi taybetî kurmancî, tê naskirin.', 'Doğru. Qanatê Kurdo dilbilimci ve kürdologdur; Kürtçenin, özellikle Kurmancînin dilbilgisi üzerine bilimsel çalışmalarıyla tanınır.', 5, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0016
('9864447e-b36e-543c-9b19-8c5b337f041c', (select id from categories where name = 'Edebiyat'), 'ku-kmr', '"kesayeta vegotinê" ew kes e ku bûyer li dora wî/wê digerin û xwîner pê re dijî. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Kesayeta vegotinê lehengê sereke yê çîrokê ye; bûyer li dora wî digerin û xwîner çîrokê bi çavê wî dişopîne.', 'Rast e. Kesayeta vegotinê lehengê sereke yê çîrokê ye; bûyer li dora wî digerin û xwîner çîrokê bi çavê wî dişopîne.', 'Doğru. Anlatı kişisi hikâyenin başkahramanıdır; olaylar onun çevresinde döner, okur hikâyeyi onun gözünden izler.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0018
