('eee41fe4-fbfe-5716-a324-0abbeec7852a', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Rast e an şaş e: "kafiye" lihevhatina dengên dawiya rêzan e ku rîtmê dide helbestê.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Kafiye dengvedana hevbeş a dawiya rêzan e; helbestê bi deng xweş dike, rîtmê çêdike û jiberkirinê hêsan dike.', 'Rast e. Kafiye dengvedana hevbeş a dawiya rêzan e; helbestê bi deng xweş dike, rîtmê çêdike û jiberkirinê hêsan dike.', 'Doğru. Kafiye, dize sonlarındaki ortak ses benzerliğidir; şiire ahenk ve ritim verir, ezberlemeyi kolaylaştırır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_ede_0024
